package com.quantpf.domain.entity;
import com.quantpf.domain.enums.*; import java.util.Objects;
public class Instrument { private final Long id; private final String instrumentCode; private final ProductType productType; private final String exchangeCode; private final String instrumentName; private InstrumentStatus status=InstrumentStatus.ACTIVE;
 public Instrument(Long id,String code,ProductType type,String exchange,String name){this.id=id;instrumentCode=Objects.requireNonNull(code);productType=Objects.requireNonNull(type);exchangeCode=Objects.requireNonNull(exchange);instrumentName=Objects.requireNonNull(name);} public Long getId(){return id;} public String getInstrumentCode(){return instrumentCode;} public ProductType getProductType(){return productType;} public String getExchangeCode(){return exchangeCode;} public String getInstrumentName(){return instrumentName;} public InstrumentStatus getStatus(){return status;} public void suspend(){status=InstrumentStatus.SUSPENDED;} public void activate(){status=InstrumentStatus.ACTIVE;} public boolean tradable(){return status==InstrumentStatus.ACTIVE;}}